CREATE POLICY audli_listening_daily_select ON listening_exercise_keys FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_exercise_rubrics;
CREATE POLICY audli_listening_daily_select ON listening_exercise_rubrics FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_lesson_owners;
CREATE POLICY audli_listening_daily_select ON listening_lesson_owners FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_generation_requests;
CREATE POLICY audli_listening_daily_select ON listening_generation_requests FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_generation_limits;
CREATE POLICY audli_listening_daily_select ON listening_generation_limits FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_jobs;
CREATE POLICY audli_listening_daily_select ON listening_jobs FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_ai_limits;
CREATE POLICY audli_listening_daily_select ON listening_ai_limits FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_library_entries;
CREATE POLICY audli_listening_daily_select ON listening_library_entries FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_daily_challenges;
CREATE POLICY audli_listening_daily_select ON listening_daily_challenges FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_select ON listening_daily_control;
CREATE POLICY audli_listening_daily_select ON listening_daily_control FOR SELECT TO audli_listening_daily USING (true);
DROP POLICY IF EXISTS audli_listening_daily_insert ON listening_generation_requests;
CREATE POLICY audli_listening_daily_insert ON listening_generation_requests FOR INSERT TO audli_listening_daily WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_insert ON listening_generation_limits;
CREATE POLICY audli_listening_daily_insert ON listening_generation_limits FOR INSERT TO audli_listening_daily WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_insert ON listening_ai_limits;
CREATE POLICY audli_listening_daily_insert ON listening_ai_limits FOR INSERT TO audli_listening_daily WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_insert ON listening_jobs;
CREATE POLICY audli_listening_daily_insert ON listening_jobs FOR INSERT TO audli_listening_daily WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_insert ON listening_library_entries;
CREATE POLICY audli_listening_daily_insert ON listening_library_entries FOR INSERT TO audli_listening_daily WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_insert ON listening_daily_challenges;
