DROP POLICY IF EXISTS audli_listening_daily_update ON listening_generation_requests;
CREATE POLICY audli_listening_daily_update ON listening_generation_requests FOR UPDATE TO audli_listening_daily USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_update ON listening_generation_limits;
CREATE POLICY audli_listening_daily_update ON listening_generation_limits FOR UPDATE TO audli_listening_daily USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_update ON listening_jobs;
CREATE POLICY audli_listening_daily_update ON listening_jobs FOR UPDATE TO audli_listening_daily USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_update ON listening_library_entries;
CREATE POLICY audli_listening_daily_update ON listening_library_entries FOR UPDATE TO audli_listening_daily USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_update ON listening_daily_challenges;
CREATE POLICY audli_listening_daily_update ON listening_daily_challenges FOR UPDATE TO audli_listening_daily USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_update ON listening_daily_control;
CREATE POLICY audli_listening_daily_update ON listening_daily_control FOR UPDATE TO audli_listening_daily USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS audli_listening_daily_delete ON listening_lesson_owners;
CREATE POLICY audli_listening_daily_delete ON listening_lesson_owners FOR DELETE TO audli_listening_daily USING (true);
COMMIT;
